(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1 = Math.sin(x*0.018+t*0.3)*Math.cos(y*0.022-t*0.2)*20;
  const warp2 = Math.cos(x*0.015-t*0.25)*Math.sin(y*0.02+t*0.35)*18;
  const warp3 = Math.sin((x+y)*0.01+t*0.4)*Math.cos((x-y)*0.012-t*0.3)*12;
  const sx = x+warp1+warp3*0.5, sy = y+warp2+warp3*0.5;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*40, 0.13, 1.8, 1.05]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    aS+=wave*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS+=Math.sin(d*f*1.3-t*sp*0.4+2.8)*w*0.5;
  }
  const act=aS/8, inh=iS/8, cor=cS/8;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.05-ang*3-t*1.5), sp2=Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3=Math.sin(dist*0.07-ang*2+t*0.9), sp4=Math.sin(dist*0.03+ang*5-t*2.0);
  const spiral=(sp1+sp2+sp3*0.5+sp4*0.3)*0.28;
  const bg1=Math.sin(sx*0.04+sy*0.025+t*0.8), bg2=Math.sin(sx*0.03-sy*0.04+t*1.1);
  const bg3=Math.sin((sx+sy)*0.12+t*2.5)*0.2, bg4=Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg=(bg1+bg2)/2+bg3+bg4;
  const domain=Math.sin(sx*0.08+t*0.5)*Math.sin(sy*0.08-t*0.4)+Math.sin((sx*0.05+sy*0.06)+t*0.7)*0.6;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const ridge=Math.abs(Math.sin(dist*0.08-ang*6-t*1.8))*Math.exp(-dist*0.004)*0.4;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2=Math.tanh((cor-inh*0.5+domain*0.4+ridge)*1.8);
  const rd3=Math.tanh((act*0.6+cor*0.4-inh*0.8+spiral*0.5+cell)*2.0);
  const reaction=rd1*0.5+rd2*0.3+rd3*0.2;
  const blend=reaction*0.7+cell*0.15+ridge*0.15, v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,42,88],[18,78,118],[24,128,142],[45,165,148],
    [120,188,130],[195,195,85],[218,165,65],[215,115,72],[188,68,82],
    [145,38,98],[88,22,72],[42,14,58],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12+Math.abs(reaction)*0.06:1.0;
  const glow=Math.max(0, 1.0-Math.abs(reaction)*2.5)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*90))|0
  ];
}
